function compute(inputs){
  const n = parseInt(inputs.n);
  let raw = inputs.probs.slice(0, n);
  let sum = raw.reduce((a,b)=>a+b,0);
  let warning = '';
  if (sum === 0) {
    warning = 'All probabilities zero; using uniform distribution.';
    raw = Array(n).fill(1/n);
    sum = 1;
  }
  const p = raw.map(x => x / sum);
  const contributions = p.map(pi => pi === 0 ? 0 : -pi * Math.log2(pi));
  const H = contributions.reduce((a,b)=>a+b,0);
  const maxH = Math.log2(n);
  const table = {
    columns: ['Outcome', 'Probability', 'Contribution (bits)'],
    rows: p.map((pi, i) => [i+1, pi.toFixed(4), contributions[i].toFixed(4)])
  };
  const insight = `Entropy = ${H.toFixed(4)} bits. Maximum for ${n} outcomes is ${maxH.toFixed(4)} bits. ${H === 0 ? 'Certainty gives zero bits.' : H === maxH ? 'Uniform distribution achieves maximum entropy.' : 'Distribution is not uniform.'}`;
  return {
    H: H,
    maxH: maxH,
    table: table,
    insight: insight,
    warning: warning
  };
}
